export interface ConnectorConfig {
  /** Stripe secret key (sk_test_... or sk_live_...) */
  stripeSecretKey: string
  /** Optional HubSpot API key for fetching contact details if not present in webhook payload */
  hubspotApiKey?: string
  /** HubSpot portal ID (required if hubspotApiKey is provided) */
  hubspotPortalId?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface HubSpotWebhookEvent {
  objectId: number
  propertyName: string
  propertyValue: string
  changeSource: string
  eventId: string
  subscriptionId: string
  portalId: string
  appId: string
  occurredAt: number
  subscriptionType: string
  attemptNumber: number
  properties?: {
    email?: string
    firstname?: string
    lastname?: string
  }
}

export type HubSpotWebhookPayload = HubSpotWebhookEvent[]

export interface StripeCustomerResponse {
  id: string
  object: string
  email: string
  name: string
  created: number
  livemode: boolean
}

export interface HandleResult {
  customerId: string
  email: string
  name: string
}

async function fetchContactDetails(
  objectId: number,
  config: ConnectorConfig
): Promise<{ email: string; firstname: string; lastname: string }> {
  if (!config.hubspotApiKey || !config.hubspotPortalId) {
    throw new Error('HubSpot API key and portal ID required to fetch contact details')
  }
  const fetch = config.fetch ?? globalThis.fetch
  const url = `https://api.hubapi.com/crm/v3/objects/contacts/${objectId}?properties=email,firstname,lastname`
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  })
  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for GET ${url}`)
  }
  const data = (await response.json()) as { properties: { email: string; firstname: string; lastname: string } }
  return data.properties
}

export async function handle(payload: HubSpotWebhookPayload, config: ConnectorConfig): Promise<HandleResult[]> {
  const fetch = config.fetch ?? globalThis.fetch
  const results: HandleResult[] = []

  for (const event of payload) {
    if (event.propertyName !== 'lifecyclestage' || event.propertyValue !== 'customer') {
      continue
    }

    let email: string | undefined
    let firstname: string | undefined
    let lastname: string | undefined

    if (event.properties?.email && event.properties?.firstname && event.properties?.lastname) {
      email = event.properties.email
      firstname = event.properties.firstname
      lastname = event.properties.lastname
    } else {
      const details = await fetchContactDetails(event.objectId, config)
      email = details.email
      firstname = details.firstname
      lastname = details.lastname
    }

    if (!email) throw new Error('Contact email is required')
    if (!firstname) throw new Error('Contact firstname is required')
    if (!lastname) throw new Error('Contact lastname is required')

    const name = `${firstname} ${lastname}`.trim()
    if (name.length > 256) {
      throw new Error('Combined name exceeds Stripe maximum of 256 characters')
    }
    if (email.length > 512) {
      throw new Error('Email exceeds Stripe maximum of 512 characters')
    }

    const stripeResponse = await fetch('https://api.stripe.com/v1/customers', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.stripeSecretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({ email, name }).toString(),
    })

    if (!stripeResponse.ok) {
      throw new Error(`Stripe API error: ${stripeResponse.status} ${stripeResponse.statusText} for POST https://api.stripe.com/v1/customers`)
    }

    const customer = (await stripeResponse.json()) as StripeCustomerResponse
    results.push({ customerId: customer.id, email: customer.email, name: customer.name })
  }

  return results
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, HubSpotWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      stripeSecretKey: 'sk_test_12345',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result).toHaveLength(1)
    expect(result[0].customerId).toBe('cus_NffrFeUfNV2Hib')
    expect(result[0].email).toBe('jennyrosen@example.com')
    expect(result[0].name).toBe('Jenny Rosen')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    baseConfig = {
      stripeSecretKey: 'sk_test_12345',
    }
  })

  it('creates Stripe customer with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        expect(req.json).toEqual({ email: 'jennyrosen@example.com', name: 'Jenny Rosen' })
        expect(req.headers.get('authorization')).toBe('Bearer sk_test_12345')
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 5151,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'evt_1',
        subscriptionId: 'sub_1',
        portalId: 'portal_1',
        appId: 'app_1',
        occurredAt: 1565104265799,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: {
          email: 'jennyrosen@example.com',
          firstname: 'Jenny',
          lastname: 'Rosen',
        },
      },
    ]

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result).toHaveLength(1)
    expect(result[0]).toEqual({
      customerId: 'cus_NffrFeUfNV2Hib',
      email: 'jennyrosen@example.com',
      name: 'Jenny Rosen',
    })
    expect(calls).toHaveLength(1)
  })

  it('uses Bearer token authentication for Stripe API', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.stripe.com/v1/customers') {
        expect(req.headers.get('authorization')).toBe('Bearer sk_live_abcdef')
        return jsonResponse({ id: 'cus_test', object: 'customer', email: 'a@b.com', name: 'Test', created: 123, livemode: true }, 201)
      }
      return jsonResponse({}, 404)
    })

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 1,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'API',
        eventId: 'e1',
        subscriptionId: 's1',
        portalId: 'p1',
        appId: 'a1',
        occurredAt: 123,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'a@b.com', firstname: 'Test', lastname: 'User' },
      },
    ]

    await handle(payload, { ...baseConfig, stripeSecretKey: 'sk_live_abcdef', fetch })
    expect(calls[0].headers.get('authorization')).toBe('Bearer sk_live_abcdef')
  })

  it('combines firstname and lastname into name field', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.stripe.com/v1/customers') {
        expect(req.json).toEqual({ email: 'john.doe@example.com', name: 'John Doe' })
        return jsonResponse({ id: 'cus_1', object: 'customer', email: 'john.doe@example.com', name: 'John Doe', created: 1, livemode: false }, 201)
      }
      return jsonResponse({}, 404)
    })

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 2,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e2',
        subscriptionId: 's2',
        portalId: 'p2',
        appId: 'a2',
        occurredAt: 456,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'john.doe@example.com', firstname: 'John', lastname: 'Doe' },
      },
    ]

    await handle(payload, { ...baseConfig, fetch })
    expect(calls[0].json).toEqual({ email: 'john.doe@example.com', name: 'John Doe' })
  })

  it('throws descriptive error when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 3,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e3',
        subscriptionId: 's3',
        portalId: 'p3',
        appId: 'a3',
        occurredAt: 789,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { firstname: 'Jane', lastname: 'Smith' },
      },
    ]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Contact email is required')
  })

  it('throws descriptive error when firstname is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 4,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e4',
        subscriptionId: 's4',
        portalId: 'p4',
        appId: 'a4',
        occurredAt: 789,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'jane@example.com', lastname: 'Smith' },
      },
    ]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Contact firstname is required')
  })

  it('throws descriptive error when lastname is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 5,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e5',
        subscriptionId: 's5',
        portalId: 'p5',
        appId: 'a5',
        occurredAt: 789,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'jane@example.com', firstname: 'Jane' },
      },
    ]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Contact lastname is required')
  })

  it('throws error with status and endpoint on non-2xx Stripe response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: { message: 'Invalid email' } }, 400))

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 6,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e6',
        subscriptionId: 's6',
        portalId: 'p6',
        appId: 'a6',
        occurredAt: 999,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'invalid', firstname: 'Test', lastname: 'User' },
      },
    ]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Stripe API error: 400 Bad Request for POST https://api.stripe.com/v1/customers'
    )
  })

  it('skips events that are not lifecycle stage customer changes', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 201))

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 7,
        propertyName: 'lifecyclestage',
        propertyValue: 'subscriber',
        changeSource: 'FORM',
        eventId: 'e7',
        subscriptionId: 's7',
        portalId: 'p7',
        appId: 'a7',
        occurredAt: 111,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'skip@example.com', firstname: 'Skip', lastname: 'Me' },
      },
      {
        objectId: 8,
        propertyName: 'email',
        propertyValue: 'new@example.com',
        changeSource: 'FORM',
        eventId: 'e8',
        subscriptionId: 's8',
        portalId: 'p8',
        appId: 'a8',
        occurredAt: 222,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'new@example.com', firstname: 'New', lastname: 'Contact' },
      },
    ]

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result).toHaveLength(0)
    expect(calls).toHaveLength(0)
  })

  it('processes multiple valid events in one payload', async () => {
    let callCount = 0
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.stripe.com/v1/customers') {
        callCount++
        return jsonResponse(
          { id: `cus_${callCount}`, object: 'customer', email: `user${callCount}@example.com`, name: `User ${callCount}`, created: callCount, livemode: false },
          201
        )
      }
      return jsonResponse({}, 404)
    })

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 10,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e10',
        subscriptionId: 's10',
        portalId: 'p10',
        appId: 'a10',
        occurredAt: 1000,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'user1@example.com', firstname: 'User', lastname: 'One' },
      },
      {
        objectId: 11,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e11',
        subscriptionId: 's11',
        portalId: 'p11',
        appId: 'a11',
        occurredAt: 1001,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'user2@example.com', firstname: 'User', lastname: 'Two' },
      },
    ]

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result).toHaveLength(2)
    expect(result[0].customerId).toBe('cus_1')
    expect(result[1].customerId).toBe('cus_2')
    expect(calls).toHaveLength(2)
  })

  it('throws error when combined name exceeds 256 characters', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const longName = 'a'.repeat(250)

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 12,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e12',
        subscriptionId: 's12',
        portalId: 'p12',
        appId: 'a12',
        occurredAt: 1200,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: 'test@example.com', firstname: longName, lastname: longName },
      },
    ]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Combined name exceeds Stripe maximum of 256 characters')
  })

  it('throws error when email exceeds 512 characters', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const longEmail = 'a'.repeat(500) + '@example.com'

    const payload: HubSpotWebhookPayload = [
      {
        objectId: 13,
        propertyName: 'lifecyclestage',
        propertyValue: 'customer',
        changeSource: 'FORM',
        eventId: 'e13',
        subscriptionId: 's13',
        portalId: 'p13',
        appId: 'a13',
        occurredAt: 1300,
        subscriptionType: 'contact.propertyChange',
        attemptNumber: 0,
        properties: { email: longEmail, firstname: 'Test', lastname: 'User' },
      },
    ]

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Email exceeds Stripe maximum of 512 characters')
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://developers.hubspot.com/docs/api-reference/legacy/webhooks/guide
// Source: https://docs.stripe.com/api/customers/create

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = [
  {
    "objectId": 5151,
    "propertyName": "lifecyclestage",
    "propertyValue": "customer",
    "changeSource": "FORM",
    "eventId": "xxxxxxx",
    "subscriptionId": "xxxxxx",
    "portalId": "xxxxxx",
    "appId": "xxxxxx",
    "occurredAt": 1565104265799,
    "subscriptionType": "contact.propertyChange",
    "attemptNumber": 0,
    "properties": {
      "email": "jennyrosen@example.com",
      "firstname": "Jenny",
      "lastname": "Rosen"
    }
  }
]

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.stripe.com/v1/customers",
    "response": {
      "id": "cus_NffrFeUfNV2Hib",
      "object": "customer",
      "email": "jennyrosen@example.com",
      "name": "Jenny Rosen",
      "created": 1680893993,
      "livemode": false
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Stripe secret key (sk_test_... or sk_live_...) */
  stripeSecretKey: string
  /** Optional HubSpot API key for fetching contact details if not present in webhook payload */
  hubspotApiKey?: string
  /** HubSpot portal ID (required if hubspotApiKey is provided) */
  hubspotPortalId?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface HubSpotWebhookEvent {
  objectId: number
  propertyName: string
  propertyValue: string
  changeSource: string
  eventId: string
  subscriptionId: string
  portalId: string
  appId: string
  occurredAt: number
  subscriptionType: string
  attemptNumber: number
  properties?: {
    email?: string
    firstname?: string
    lastname?: string
  }
}

export type HubSpotWebhookPayload = HubSpotWebhookEvent[]

export interface StripeCustomerResponse {
  id: string
  object: string
  email: string
  name: string
  created: number
  livemode: boolean
}

export interface HandleResult {
  customerId: string
  email: string
  name: string
}

async function fetchContactDetails(
  objectId: number,
  config: ConnectorConfig
): Promise<{ email: string; firstname: string; lastname: string }> {
  const fetch = config.fetch ?? globalThis.fetch
  const url = `https://api.hubapi.com/crm/v3/objects/contacts/${objectId}?properties=email,firstname,lastname`
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  })
  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for GET ${url}`)
  }
  const data = (await response.json()) as { properties: { email: string; firstname: string; lastname: string } }
  return data.properties
}

export async function handle(payload: HubSpotWebhookPayload, config: ConnectorConfig): Promise<HandleResult[]> {
  const fetch = config.fetch ?? globalThis.fetch
  const results: HandleResult[] = []

  for (const event of payload) {
    if (event.propertyName !== 'lifecyclestage' || event.propertyValue !== 'customer') {
      continue
    }

    let email: string | undefined
    let firstname: string | undefined
    let lastname: string | undefined

    if (event.properties?.email && event.properties?.firstname && event.properties?.lastname) {
      email = event.properties.email
      firstname = event.properties.firstname
      lastname = event.properties.lastname
    } else {
      if (!config.hubspotApiKey || !config.hubspotPortalId) {
        if (!event.properties?.email) throw new Error('Contact email is required')
        if (!event.properties?.firstname) throw new Error('Contact firstname is required')
        if (!event.properties?.lastname) throw new Error('Contact lastname is required')
      }
      const details = await fetchContactDetails(event.objectId, config)
      email = details.email
      firstname = details.firstname
      lastname = details.lastname
    }

    if (!email) throw new Error('Contact email is required')
    if (!firstname) throw new Error('Contact firstname is required')
    if (!lastname) throw new Error('Contact lastname is required')

    const name = `${firstname} ${lastname}`.trim()
    if (name.length > 256) {
      throw new Error('Combined name exceeds Stripe maximum of 256 characters')
    }
    if (email.length > 512) {
      throw new Error('Email exceeds Stripe maximum of 512 characters')
    }

    const stripeResponse = await fetch('https://api.stripe.com/v1/customers', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.stripeSecretKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email, name }),
    })

    if (!stripeResponse.ok) {
      throw new Error(`Stripe API error: ${stripeResponse.status} ${stripeResponse.statusText} for POST https://api.stripe.com/v1/customers`)
    }

    const customer = (await stripeResponse.json()) as StripeCustomerResponse
    results.push({ customerId: customer.id, email: customer.email, name: customer.name })
  }

  return results
}

